package dev.interview.orders.order;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.interview.orders.audit.*; import dev.interview.orders.outbox.*; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class OrderServiceTest {OrderRepository orders=mock(OrderRepository.class);OutboxRepository outbox=mock(OutboxRepository.class);AuditRepository audit=mock(AuditRepository.class);OrderService service=new OrderService(orders,outbox,audit,new ObjectMapper().findAndRegisterModules());
 @Test void createsOrderAndAtomicOutboxRecord(){when(orders.findByIdempotencyKey("key-1")).thenReturn(Optional.empty());when(orders.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));var result=service.create("alice","key-1",new OrderDtos.CreateOrder("SKU-1",2,new BigDecimal("9.99")));assertThat(result.status()).isEqualTo(OrderStatus.CREATED);verify(outbox).save(any());verify(audit).save(any());}
 @Test void repeatedKeyReturnsSameOrderWithoutAnotherWrite(){var existing=new CustomerOrder(UUID.randomUUID(),"alice","SKU-1",1,BigDecimal.ONE,"key-1");when(orders.findByIdempotencyKey("key-1")).thenReturn(Optional.of(existing));var result=service.create("alice","key-1",new OrderDtos.CreateOrder("ignored",2,BigDecimal.TEN));assertThat(result.id()).isEqualTo(existing.getId());verify(orders,never()).saveAndFlush(any());verifyNoInteractions(outbox,audit);}
 @Test void customerCannotReadAnotherCustomersOrder(){var existing=new CustomerOrder(UUID.randomUUID(),"alice","SKU-1",1,BigDecimal.ONE,"key-1");when(orders.findById(existing.getId())).thenReturn(Optional.of(existing));assertThatThrownBy(()->service.get(existing.getId(),"bob",false)).isInstanceOf(SecurityException.class);}
}
